875	  * @param  BufferLength: buffer's length
876	  * @retval 0   : pBuffer1 identical to pBuffer2
877	  *         > 0 : pBuffer1 differs from pBuffer2
878	  */
879	static uint16_t Buffercmp(uint8_t* pBuffer1, uint8_t* pBuffer2, uint16_t BufferLength)
880	{
